function contactDetails(context='general',id=''){
 const configured=String(window.MonarcaStoreContact?.whatsappNumber||'').trim();
 const western=configured.replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
 const clean=/^[+\d\s()-]+$/.test(western)?western.replace(/[\s()+-]/g,''):'';
 const number=/^9647\d{9}$/.test(clean)?clean:'';
 const order=['order','tracking'].includes(context)?state.orders.find(o=>o.id===String(id)&&/^[A-Z0-9][A-Z0-9-]{0,59}$/i.test(o.id)):null;
 const orderId=order?.id||'';
 const message=orderId?(context==='tracking'?`مرحباً Monarca، أود الاستفسار عن توصيل طلبي رقم ${orderId}.`:`مرحباً Monarca، أحتاج مساعدة بخصوص طلبي رقم ${orderId}.`):context==='address'?'مرحباً Monarca، أحتاج مساعدة في إضافة عنوان التوصيل.':'مرحباً Monarca، أود الاستفسار عن منتجاتكم.';
 return {mode:number?'live':'demo',numberText:number?'+'+number:'+964 7XX XXX XXXX',href:number?'https://wa.me/'+number+'?text='+encodeURIComponent(message):'',message,orderId,context:orderId?context:context==='address'?'address':'general'};
}
