function home(){const curLang=window.MonarcaI18n?.language()||'ar';const compactLangBtn=`<button type="button" class="header-lang-compact" data-action="quick-lang" data-val="${curLang==='ar'?'en':'ar'}" title="${curLang==='ar'?'Switch to English':'التبديل إلى العربية'}"><span>${curLang==='ar'?'EN':'عربي'}</span></button>`;const desktopLangPill=`<div class="header-lang-switch desktop-only-lang" title="Switch Language / تبديل اللغة"><button type="button" class="lang-opt ${curLang==='ar'?'active':''}" data-action="quick-lang" data-val="ar">العربية</button><button type="button" class="lang-opt ${curLang==='en'?'active':''}" data-action="quick-lang" data-val="en">English</button></div>`;return `<div class="announcement monarca-announcement">${icon('truck')} <span>${curLang==='en'?'Fast Delivery across all 18 Iraq Governorates · Free shipping over $75 USD':'التوصيل السريع لكافة محافظات العراق الـ ١٨ · شحن مجاني للطلبات فوق ٧٥ دولار'}</span> ${icon('truck')}</div><header class="home-header monarca-header"><div class="brand-row"><button class="icon-btn photo-entry" data-go="camera" aria-label="البحث بالصورة">${icon('camera')}</button><button class="monarca-wordmark" data-go="home" aria-label="Monarca">Monarca<span class="monarca-wing" aria-hidden="true"></span></button><nav class="desktop-nav-links" aria-label="Desktop Navigation"><a href="#home" class="desktop-nav-link active">${localizeText('الرئيسية')}</a><a href="#categories" class="desktop-nav-link">${localizeText('الأقسام')}</a><a href="#wishlist" class="desktop-nav-link">${localizeText('المفضلة')}</a><a href="#cart" class="desktop-nav-link">${localizeText('السلة')}</a><a href="#account" class="desktop-nav-link">${localizeText('حسابي')}</a>${desktopLangPill}</nav>${compactLangBtn}<button class="icon-btn" data-go="menu" aria-label="فتح القائمة"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16M4 12h16M4 19h16"/></svg></button></div></header><section class="monarca-hero" aria-label="مجموعة أناقة خالدة"><div class="monarca-hero-copy"><h1>أناقة خالدة</h1><p>تفاصيل صغيرة تصنع فرقاً كبيراً</p><button data-action="home-category" data-value="all">تسوّق الآن ${icon('arrow')}</button></div></section><nav class="round-categories" aria-label="تسوّقي حسب القسم">${[['clothes','ملابس',2],['bags','حقائب',0],['shoes','أحذية',1],['accessories','إكسسوارات',6]].map(([c,n,img])=>`<button data-action="home-category" data-value="${c}" aria-label="${n}">${photo({img,name:n},'','category')}<b>${n}</b></button>`).join('')}</nav>${window.Monarca?.sourceSections?.()||''}${bestSellersSection()}<section class="home-products"><div class="section-head"><h2>منتجات مختارة</h2><button data-action="home-category" data-value="all">عرض الكل ${icon('arrow')}</button></div>${grid([products[4],products[2],products[5],products[0]],'home')}</section><button class="monarca-delivery" data-action="delivery">${icon('pin')} التوصيل إلى ${esc(ui.deliveryCity||state.address?.city||'بغداد')} ${icon('chevron')}</button><div class="benefits"><div>${icon('truck')}توصيل داخل العراق</div><div>${icon('card')}Visa · Mastercard</div><div>${icon('shield')}تسوّق بثقة</div></div><section class="journal"><small>FIND YOUR INSPIRATION</small><h3>أعجبتك قطعة في صورة؟</h3><button class="text-link" data-go="camera">ابحثي عن قطع مشابهة ${icon('camera')}</button></section><div class="section-head"><h2>اكتشفي أكثر</h2><button data-go="search">البحث عن المنتجات ${icon('search')}</button></div><div class="page-content" style="padding-top:0">${goto('قسائم الخصم','coupons','secondary')}</div><div class="app-footer">MONARCA · TIMELESS ELEGANCE</div>${desktopFooter()}`;}

function search(){return `${top('ابحثي عن إلهامك')}<div class="page-content"><form id="search-form"><label class="sr-only" for="search-input">ابحث عن المنتجات</label><div class="input-wrap">${icon('search')}<input id="search-input" name="query" type="search" value="${esc(ui.query)}" placeholder="حقائب، قمصان، أحذية..." autocomplete="off"><button class="icon-btn" type="submit" aria-label="بحث">${icon('arrow')}</button></div></form><div class="inline-row" style="margin:24px 0 14px"><h2 style="font-size:14px;font-weight:500">عمليات بحث رائجة</h2><span class="overline">THE SEARCH EDIT</span></div>${['حقيبة','ساتان','حذاء رياضي','جاكيت'].map(t=>`<button class="recent-item" data-action="search-term" data-value="${t}">${icon('clock')}${t}${icon('arrow')}</button>`).join('')}<div class="divider"></div><div class="info-box">${icon('camera')}<div>لديك صورة لقطعة أعجبتك؟<br>ابحثي بالصورة واكتشفي منتجات مشابهة.</div></div><div class="button-stack">${goto(icon('camera')+' البحث بالصورة','camera','secondary')}</div></div>`;}
function filtered(){let ps=products.filter(p=>(ui.category==='all'||ui.category==='offers'&&p.old||p.cat===ui.category)&&p.price<=ui.max);const q=ui.query.trim().toLowerCase();if(q)ps=ps.filter(p=>(p.name+' '+p.keywords+' '+p.material).toLowerCase().includes(q));if(ui.sort==='low')ps.sort((a,b)=>a.price-b.price);if(ui.sort==='high')ps.sort((a,b)=>b.price-a.price);if(ui.sort==='new')ps.reverse();return ps;}
function results(){const ps=filtered();const title=ui.query?`نتائج «${esc(ui.query)}»`:ui.category==='offers'?'مختارات بأسعار خاصة':categories.find(c=>c[0]===ui.category)?.[1]||'كل المنتجات';return `${top(title,`<button class="icon-btn" data-go="search" aria-label="بحث">${icon('search')}</button>`)}<div class="filter-toolbar"><small>${ar(ps.length)} منتجات · مختارة لك</small><button data-action="filter">${icon('filter')} تصفية وترتيب</button></div>${ui.max<commerce.priceCeiling||ui.sort!=='recommended'||ui.category!=='all'?`<div class="applied-filter"><span>${esc(categories.find(c=>c[0]===ui.category)?.[1]||'العروض')} · حتى ${money(ui.max)}</span><button data-action="clear-filter" aria-label="مسح التصفية">${icon('close')}</button></div>`:''}${ps.length?grid(ps):empty('لا توجد نتائج مطابقة','جرّبي كلمات أخرى أو امسحي عوامل التصفية.','search','تعديل البحث','search')}${!ps.length?btn('مسح التصفية وإظهار الكل','clear-all','text-btn','style="display:block;margin:auto"'):''}`;}
function categoriesView(){return `${top('الأقسام',`<button class="icon-btn" data-go="search" aria-label="بحث">${icon('search')}</button>`)}<div class="page-content"><p class="overline">THE COLLECTIONS</p><h2 class="page-subtitle">لكل يوم، قطعة مميزة.</h2><div class="category-list">${[['clothes','الملابس',2],['bags','الحقائب',0],['shoes','الأحذية',1],['accessories','الإكسسوارات',6]].map(([id,n,img])=>`<button class="category-tile" data-action="home-category" data-value="${id}">${photo({img,name:n},'','category')}<span>${n}</span></button>`).join('')}</div><div class="button-stack">${btn('استكشفي كل المنتجات '+icon('arrow'),'home-category','secondary','data-value="all"')}</div></div>`;}
function camera(){return `${top('البحث بالصورة')}<div class="page-content"><p class="overline">SEE IT. FIND IT. LOVE IT.</p><h2 class="page-subtitle">صورتك، بداية الإلهام.</h2><p class="page-intro">التقطي صورة أو اختاري من جهازك لاكتشاف قطع مشابهة. يُفضّل أن تظهر قطعة واحدة بوضوح.</p><div class="camera-frame">${ui.photo?`<img class="camera-preview" src="${esc(ui.photo)}" alt="صورتك المختارة">`:ui.photoSample!==null?`${photo({img:ui.photoSample,name:'صورة تجربة البحث'},'camera-sample')}`:icon('camera')+'<p>ضعي القطعة داخل الإطار</p>'}${ui.photoScanning?'<span class="scan-line"></span><span class="scanning-label">جارٍ البحث عن منتجات مشابهة…</span>':''}</div>${ui.photoError?`<p class="photo-error" role="alert">${esc(ui.photoError)}</p>`:''}<div class="button-stack" style="margin-top:0"><label class="primary file-label" tabindex="0">${icon('upload')} اختر من الصور<input class="sr-only" type="file" id="photo-file" accept="image/jpeg,image/png,image/webp,image/avif"></label><label class="secondary file-label" tabindex="0">${icon('camera')} التقط صورة<input class="sr-only" type="file" id="camera-file" accept="image/*" capture="environment"></label>${btn(ui.photoScanning?'جارٍ البحث…':'اعثر على قطع مشابهة','scan','primary',ui.photoScanning?'disabled':'')}</div><p class="field-note" style="margin-top:15px">لا يتم إرسال صورك إلى خادم. نتائج البحث هنا توضيحية لتجربة التصميم.</p><div class="divider"></div><p style="font-size:11px">أو جرّبي صورة من المجموعة</p><div class="sample-picks">${[0,1,2].map(i=>`<button class="sample-pick" data-action="photo-sample" data-value="${i}" aria-label="جرّب صورة ${products[i].name}">${photo(products[i])}</button>`).join('')}</div><div class="pill-row">${btn('تجربة: دون نتائج','photo-none','pill')}${btn('تجربة: تعذّر البحث','photo-fail','pill')}${btn('مساعدة الكاميرا','camera-help','pill')}</div></div>`;}
function photoResults(){let ps=products.filter(p=>p.img===ui.photoSample);if(!ps.length)ps=[products[0],products[2]];ps=[...ps,...products.filter(p=>!ps.includes(p)).slice(0,3)];return `${top('منتجات مشابهة لصورتك')}<div class="photo-results-head">${ui.photo?`<img src="${esc(ui.photo)}" alt="صورتك">`:photo(products[ui.photoSample||0])}<div><p>إلهام من صورتك</p><small>نتائج توضيحية · محاكاة البحث بالصورة</small></div><button class="icon-btn" data-go="camera" aria-label="صورة أخرى">${icon('edit')}</button></div>${ui.photoResult==='none'?empty('لم نعثر على قطع مشابهة','جرّبي صورة أوضح أو تصفّحي مجموعتنا.','image','جرّب صورة أخرى','camera'):grid(ps)}<div class="page-content" style="padding-top:0">${goto('جرّب صورة أخرى','camera','secondary')}</div>`;}
function productView(id){const p=product(id);if(ui.productId!==p.id){ui.productId=p.id;ui.selectedColor=p.colors[0];ui.selectedSize=p.sizes.length===1?p.sizes[0]:'';ui.gallery=0;}return `${top('تفاصيل القطعة',`<button class="icon-btn" data-go="cart" aria-label="السلة">${icon('bag')}</button>`)}<div class="product-view-desktop-grid"><div class="product-hero-pane"><div class="product-hero">${photo(p)}<button class="favorite-btn ${state.wish.includes(p.id)?'saved':''}" data-action="wish" data-id="${p.id}" aria-label="المفضلة" aria-pressed="${state.wish.includes(p.id)}">${icon('heart')}</button><span class="badge">MONARCA / THE ESSENTIALS</span></div></div></div><div class="product-detail-pane"><div class="product-detail"><div class="inline-row"><span class="overline">${p.en.toUpperCase()}</span><span class="rating">${icon('star')} 4.8 <span class="muted">· تقييم توضيحي</span></span></div><h1>${p.name}</h1><p class="page-intro" style="margin-bottom:12px">${p.material}</p><div class="price">${money(p.price)}${p.old?`<span class="old-price">${money(p.old)}</span>`:''}</div><div class="option-label"><span>اللون: <b style="font-weight:400">${colors[ui.selectedColor][0]}</b></span></div><div class="pill-row">${p.colors.map(c=>`<button class="color-option ${ui.selectedColor===c?'active':''}" data-action="color" data-value="${c}" aria-pressed="${ui.selectedColor===c}"><i style="background:${colors[c][1]}"></i>${colors[c][0]}</button>`).join('')}</div>${p.colors.length>1?'<p class="field-note" style="margin-top:8px">الصورة للون البني؛ اللون الآخر موضح بالعينة.</p>':''}<div class="option-label"><span>المقاس ${ui.selectedSize?`· ${ui.selectedSize}`:'<span class="accent">· اختاري المقاس</span>'}</span><button class="text-btn" style="padding:0" data-action="size-guide">دليل المقاسات</button></div><div class="pill-row">${p.sizes.map(s=>`<button class="size-option ${s===ui.selectedSize?'active':''}" data-action="size" data-value="${s}" ${s===p.unavailable?'disabled aria-label="'+s+' غير متوفر"':''} aria-pressed="${ui.selectedSize===s}">${s}</button>`).join('')}</div><p class="stock-note">${p.stock<=2?'بقيت قطعتان فقط':'متوفر · جاهز لإضافته إلى سلتك'}</p><div class="info-box">${icon('truck')}<div>التوصيل إلى ${esc(ui.deliveryCity||state.address?.city||'بغداد')}<br>المتوفر في العراق: نحو يومين. الطلب من الصين: ١٥–٢٠ يوماً · الدفع حسب مصدر القطعة</div></div><div style="margin-top:20px">${[['detail','التفاصيل والعناية','قطعة مختارة لإطلالة يومية متكاملة. اتّبعي تعليمات العناية على الملصق الداخلي. مواصفات المنتج هنا بيانات عرض وتحتاج اعتماد العميل قبل البيع.'],['delivery','التوصيل والاستبدال','رسوم التوصيل التجريبية ٤ USD للطلب، والتوصيل مجاني من ٧٥ USD قبل الخصم. المتوفر في العراق يصل خلال نحو يومين، والطلب من الصين خلال ١٥–٢٠ يوماً.']].map(([k,t,b])=>`<button class="accordion" data-action="accordion" data-value="${k}" aria-expanded="${!!ui.accordion[k]}">${t}${icon('plus')}</button>${ui.accordion[k]?`<div class="accordion-body">${b}</div>`:''}`).join('')}</div></div><div class="section-head"><h2>قد يعجبك أيضاً</h2></div><div class="product-desktop-actions">${btn(icon('bag')+' أضف إلى السلة','add-cart','primary')}${btn('اشترِ الآن','buy-now','secondary')}</div></div></div></div><div class="section-head"><h2>قد يعجبك أيضاً</h2></div>${grid(products.filter(x=>x.id!==p.id).slice(0,4))}`;}
function wish(){const ps=products.filter(p=>state.wish.includes(p.id));return `${top('المفضلة')}${ps.length?`<p class="page-intro" style="padding:18px 18px 0">قطع أحببتِها، لتعودي إليها متى شئتِ.</p>${grid(ps)}`:empty('مساحة لقطعك المفضلة','اضغطي على القلب بجانب أي قطعة لحفظها هنا.','heart','اكتشفي المجموعة','home')}`;}
function cartView(){if(!state.cart.length)return top('سلة التسوّق')+empty('سلتك تنتظر اختياراتك','أضيفي قطعة تحبينها، ودعينا نكمل إطلالتك.');const t=total();return `${top('سلة التسوّق')}<div class="page-content cart-page-content" style="padding-top:2px"><div class="cart-view-desktop-grid"><div class="cart-items-pane">${state.cart.map((l,i)=>{const p=product(l.id);return `<article class="cart-line"><button class="product-photo img-${p.img}" data-go="product/${p.id}" aria-label="${p.name}">${photoArt(p.img)}</button><div class="cart-line-info"><div class="inline-row"><h3>${p.name}</h3><button class="icon-btn" data-action="remove-cart" data-index="${i}" aria-label="إزالة ${p.name}">${icon('trash')}</button></div><p>${colors[l.color][0]} · ${l.size}</p><div class="inline-row"><span class="price">${money(p.price*l.qty)}</span><div class="quantity"><button data-action="qty-minus" data-index="${i}" aria-label="تقليل الكمية" ${l.qty===1?'disabled':''}>−</button><span>${ar(l.qty)}</span><button data-action="qty-plus" data-index="${i}" aria-label="زيادة الكمية" ${l.qty>=p.stock?'disabled':''}>+</button></div></div></div></article>`;}).join('')}</div><div class="cart-summary-pane"><div class="free-shipping">${t.subtotal>=commerce.shipping.freeFrom?'طلبك مؤهل للتوصيل المجاني':`بقي ${money(commerce.shipping.freeFrom-t.subtotal)} للتوصيل المجاني`}<div class="progress"><span style="width:${Math.min(100,t.subtotal/commerce.shipping.freeFrom*100)}%"></span></div></div><form id="coupon-form" class="coupon-inline"><input name="code" aria-label="رمز الخصم" placeholder="رمز الخصم · جرّبي M10" value="${esc(state.coupon)}"><button type="submit">تطبيق</button></form>${state.coupon?`<div class="inline-row" style="margin-top:12px"><small class="green">تم تطبيق ${esc(state.coupon)}</small>${btn('إزالة القسيمة','remove-coupon','text-btn')}</div>`:''}${summary(t)}<div class="cart-desktop-checkout-action">${btn(`إتمام الطلب · ${money(t.total)} ${icon('arrow')}`,'checkout','primary btn-block')}</div><p class="field-note" style="margin-top:12px">الرسوم والخصومات قواعد تجريبية. يتحدّث التوصيل بعد اختيار عنوانك.</p></div></div></div><div class="checkout-bar mobile-only-bar">${btn(`إتمام الطلب · ${money(t.total)} ${icon('arrow')}`,'checkout')}</div>`;}
function addressForm(){const a={...(state.address||{}),...ui.addressDraft};return `${top('عنوان التوصيل')}<div class="page-content"><div class="steps"><span class="current"><i>١</i>العنوان</span><span><i>٢</i>الدفع</span><span><i>٣</i>التأكيد</span></div><p class="page-intro">أضيفي عنواناً واضحاً لنتمكن من إيصال طلبك بسهولة.</p><form id="address-form" novalidate><div class="form-error" id="address-error" role="alert"></div><label class="field"><span>الاسم الكامل *</span><input name="name" autocomplete="name" value="${esc(a.name||'')}" placeholder="الاسم واسم العائلة" required></label><label class="field"><span>رقم الهاتف العراقي *</span><input name="phone" type="tel" dir="ltr" inputmode="tel" autocomplete="tel" value="${esc(a.phone||'')}" placeholder="+964 7XX XXX XXXX" required></label><label class="field"><span>المحافظة / المدينة *</span><select name="city" required><option value="">اختاري المدينة</option>${cities.map(c=>`<option ${a.city===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="field-row"><label class="field"><span>المنطقة / الحي *</span><input name="area" value="${esc(a.area||'')}" placeholder="مثال: المنصور" required></label><label class="field"><span>الشارع *</span><input name="street" value="${esc(a.street||'')}" placeholder="اسم الشارع" required></label></div><label class="field"><span>أقرب نقطة دالة *</span><input name="landmark" value="${esc(a.landmark||'')}" placeholder="مثال: قرب مول المنصور" required></label><div class="field-row"><label class="field"><span>رقم المبنى (اختياري)</span><input name="building" value="${esc(a.building||'')}" placeholder="رقم المبنى"></label><label class="field"><span>الشقة / الطابق (اختياري)</span><input name="apartment" value="${esc(a.apartment||'')}" placeholder="رقم الشقة"></label></div><label class="field"><span>ملاحظات التوصيل (اختياري)</span><textarea name="note" placeholder="أي تفاصيل تساعد المندوب">${esc(a.note||'')}</textarea></label><div class="info-box">${icon('info')}استخدمي بيانات وهمية أثناء تجربة هذا النموذج.</div><div class="button-stack"><button class="primary" type="submit">${ui.addressReturn==='checkout'?'حفظ ومتابعة الطلب':'حفظ العنوان'} ${icon('arrow')}</button>${btn('تعبئة بيانات تجريبية','fill-address','secondary')}</div></form></div>`;}
function addressCard(a){return `<div class="address-card"><div class="inline-row"><b>${icon('pin')} ${esc(a.name)}</b><button class="text-btn" data-action="edit-address" style="padding:0">تعديل</button></div><p>${esc(addressPlace(a))} · ${esc(a.area)} · ${esc(a.street)}<br>${esc(a.landmark)}${a.building?'<br>المبنى '+esc(a.building):''}${a.apartment?' · '+esc(a.apartment):''}<br><span class="ltr">${esc(a.phone)}</span></p></div>`;}
function addresses(){return `${top('عناويني')}<div class="page-content">${state.address?addressCard(state.address):empty('لم تُضف أي عنوان بعد','أضيفي عنوانك لتصبح تجربة التسوق أسهل.','pin','إضافة عنوان','address')}${state.address?btn('تعديل عنوان التوصيل','edit-address','secondary'):''}<p class="field-note" style="margin-top:20px">يحفظ هذا النموذج عنوان توصيل واحداً على جهازك.</p></div>`;}
function checkout(){if(!shoppingLines().length)return top('إتمام الطلب')+empty('سلتك فارغة','أضيفي قطعة أولاً لإكمال الطلب.');return `${top('إتمام الطلب')}<div class="page-content checkout-page-content" style="padding-top:0"><div class="checkout-desktop-grid"><div class="checkout-main-pane"><div class="steps"><span><i>✓</i>العنوان</span><span class="current"><i>٢</i>الدفع</span><span><i>٣</i>التأكيد</span></div><div class="section-head" style="margin:0 0 13px"><h2 style="font-size:14px">عنوان التوصيل</h2></div>${state.address?addressCard(state.address):btn('إضافة عنوان التوصيل','edit-address','secondary')}<div class="option-label"><span>طريقة الدفع</span><small class="muted">اختاري الطريقة المناسبة</small></div>${[['visa','card','Visa','ادفعي باستخدام بطاقة Visa · محاكاة'],['mastercard','card','Mastercard','ادفعي باستخدام بطاقة Mastercard · محاكاة']].map(([v,i,t,s])=>`<button class="payment-option ${ui.payment===v?'active':''}" data-action="payment-method" data-value="${v}" aria-pressed="${ui.payment===v}">${cardBrand(v)}<span>${t}<small>${s}</small></span><i class="radio"></i></button>`).join('')}<div class="info-box">${icon('shield')}طلب تجريبي فقط؛ لن يُرسل طلب حقيقي أو يُخصم مبلغ.</div></div><div class="checkout-summary-pane"><div class="checkout-summary-card"><div class="option-label"><span>ملخص الطلب · ${ar(shoppingLines().reduce((s,l)=>s+l.qty,0))} قطع${ui.buyNow?' · شراء مباشر':''}</span><button class="text-btn" data-go="${ui.buyNow?'product/'+ui.buyNow[0].id:'cart'}" style="padding:0">تعديل</button></div>${shoppingLines().map(l=>`<div class="mini-product">${photo(product(l.id))}<div>${product(l.id).name}<small>${colors[l.color][0]} · ${l.size} · الكمية ${ar(l.qty)}</small>${money(product(l.id).price*l.qty)}</div></div>`).join('')}${summary()}<p class="field-note" style="margin-top:12px">المتوفر في العراق: نحو يومين. الطلب من الصين: ١٥–٢٠ يوماً. الأسعار والشحن بيانات تجريبية.</p><label class="checkbox-row"><input type="checkbox" id="terms" checked> أوافق على <button type="button" class="text-btn" style="padding:0;font-size:10px" data-go="policy">شروط التجربة وسياسة المتجر</button></label><div class="checkout-desktop-pay-action">${btn(`${ui.placing?'جارٍ تأكيد الطلب…':'متابعة الدفع التجريبي'} · ${money(total().total)}`,'confirm-order','primary btn-block',ui.placing?'disabled':'')}</div></div></div></div></div><div class="checkout-bar mobile-only-bar">${btn(`${ui.placing?'جارٍ تأكيد الطلب…':'متابعة الدفع التجريبي'} · ${money(total().total)}`,'confirm-order','primary',ui.placing?'disabled':'')}</div>`;}
function payment(){return `${top('الدفع التجريبي')}<div class="page-content"><div class="steps"><span><i>✓</i>العنوان</span><span class="current"><i>٢</i>الدفع</span><span><i>٣</i>التأكيد</span></div><div class="info-box">${icon('shield')}هذه محاكاة. لا تُدخل بيانات بطاقة حقيقية. لن يتم خصم أي مبلغ.</div><div style="background:var(--brown);color:#f8f6f2;padding:26px;margin:22px 0"><div class="inline-row"><span style="font:14px Georgia;letter-spacing:2px">${cardName(ui.payment).toUpperCase()} / DEMO</span>${cardBrand(ui.payment)}</div><p class="ltr" style="font:20px Georgia;letter-spacing:3px;margin:30px 0 17px">${ui.payment==='mastercard'?'5555 ···· ···· 4444':'4242 ···· ···· 4242'}</p><small style="letter-spacing:1px">PROTOTYPE ONLY · NOT A REAL CARD</small></div><div class="inline-row" style="font-size:15px"><span>إجمالي الدفع</span><b style="font-weight:500">${money(total().total)}</b></div><div class="button-stack">${btn(ui.placing?'جارٍ المعالجة…':icon('check')+' محاكاة دفع ناجح','pay-success','primary',ui.placing?'disabled':'')}${btn('محاكاة دفع غير ناجح','pay-fail','secondary',ui.placing?'disabled':'')}${btn('تغيير طريقة الدفع','change-card','text-btn')}</div><p class="field-note">نتيجة الدفع هنا تختارينها لاختبار مساري النجاح والفشل في التصميم.</p></div>`;}
function orderBy(id){return state.orders.find(o=>o.id===id);}
const statusText={placed:'تم التأكيد',preparing:'قيد التجهيز',shipped:'تم الشحن',delivered:'تم التسليم',cancelled:'تم الإلغاء',returned:'طلب إرجاع قيد المراجعة'};
function success(){const o=orderBy(ui.lastOrder||state.lastOrder);if(!o)return top('تم الطلب')+empty('لا يوجد طلب بعد','ابدئي بتجربة تسوق جديدة.');return `${top('تأكيد الطلب')}<div class="page-content success-content"><div class="success-mark">${icon('check')}</div><p class="overline">THANK YOU FOR CHOOSING MONARCA</p><h1>اختيار جميل.<br>طلبك تأكّد!</h1><p>تم حفظ طلبك التجريبي بنجاح.<br>يمكنك الآن متابعة تفاصيله وحالة التوصيل.</p><div class="order-id"><span>رقم الطلب </span><b class="ltr">${o.id}</b></div>${summary(o)}<p>الدفع: ${cardName(o.payment)} · دفع تجريبي<br>إلى ${esc(addressPlace(o.address))} · ${esc(o.address.area)}</p><div class="button-stack">${goto('عرض تفاصيل الطلب '+icon('arrow'),'order/'+o.id)}${goto('متابعة التسوق','home','secondary')}</div><p class="field-note">هذا طلب تجريبي على جهازك، ولا يتضمن شحناً أو دفعاً حقيقياً.</p></div>`;}
function orders(){const os=state.orders.filter(o=>ui.orderFilter==='all'||(ui.orderFilter==='active'?['placed','preparing','shipped'].includes(o.status):ui.orderFilter==='delivered'?o.status==='delivered':(['cancelled','returned'].includes(o.status)||o.returnRequests?.length)));return `${top('طلباتي')}<div class="page-content"><div class="pill-row" style="margin-bottom:20px">${[['all','الكل'],['active','قيد التنفيذ'],['delivered','تم التسليم'],['other','الملغاة والإرجاع']].map(([v,n])=>btn(n,'order-filter','pill '+(ui.orderFilter===v?'active':''),`data-value="${v}"`)).join('')}</div>${os.length?`<div class="orders-grid">`+os.map(o=>`<article class="order-card"><div class="inline-row"><span class="ltr">${o.id}</span><span class="order-status ${o.status==='cancelled'?'cancelled':''}">${statusText[o.status]}</span></div><p>${o.date}${o.sample?' · طلب توضيحي':''}${o.returnRequests?.length?' · إرجاع قيد المراجعة':''}</p><div class="order-thumbs">${o.items.map(l=>photo(product(l.id))).join('')}</div><div class="inline-row"><span class="price">${money(o.total)}</span>${goto('عرض التفاصيل','order/'+o.id,'text-btn')}</div></article>`).join('')+`</div>`:empty('لا توجد طلبات هنا','ستظهر الطلبات المطابقة للحالة هنا.','box','تصفّحي المجموعة','home')}<p class="field-note">كل الطلبات في هذه النسخة تجريبية. الطلبات المسبقة موضّحة بعبارة «طلب توضيحي».</p></div>`;}
function availableReturns(o){return o.items.map((l,i)=>({line:l,index:i,remaining:l.qty-(o.returnRequests||[]).filter(r=>r.itemIndex===i).reduce((n,r)=>n+r.qty,0)})).filter(r=>r.remaining>0);}
function returnRequests(o){return (o.returnRequests||[]).map(r=>`<div class="info-box" style="margin-top:12px">${icon('return')}<div>طلب إرجاع تجريبي · قيد المراجعة<br>${product(o.items[r.itemIndex].id).name} · ${o.items[r.itemIndex].size} · الكمية ${ar(r.qty)}<br>السبب: ${esc(r.reason)}${r.note?'<br>'+esc(r.note):''}<br>لا يتم تنفيذ استرداد مالي حقيقي.</div></div>`).join('');}
function orderDetail(id){const o=orderBy(id);if(!o)return top('تفاصيل الطلب')+empty('لم يتم العثور على الطلب','راجعي قائمة طلباتك.','box','طلباتي','orders');return `${top('تفاصيل الطلب')}<div class="page-content"><div class="inline-row"><span class="ltr">${o.id}</span><span class="order-status ${o.status==='cancelled'?'cancelled':''}">${statusText[o.status]}</span></div><p class="field-note" style="margin:12px 0">${o.date}${o.sample?' · طلب توضيحي':''}</p>${o.items.map(l=>`<div class="cart-line">${photo(product(l.id))}<div class="cart-line-info"><h3>${product(l.id).name}</h3><p>${colors[l.color][0]} · ${l.size} · ${ar(l.qty)} قطع</p><span class="price">${money(l.price*l.qty)}</span></div></div>`).join('')}${summary(o)}<div class="divider"></div><h2 style="font-size:14px;font-weight:500">عنوان التوصيل</h2><p class="page-intro" style="margin-top:10px">${esc(o.address.name)}<br>${esc(addressPlace(o.address))} · ${esc(o.address.area)} · ${esc(o.address.street)}<br>${esc(o.address.landmark)}<br><span class="ltr">${esc(o.address.phone)}</span></p><div class="info-box">${cardBrand(o.payment)}الدفع عبر ${cardName(o.payment)} · محاكاة · بيانات محفوظة لحظة الطلب</div><div class="button-stack">${!['cancelled','returned'].includes(o.status)?goto('تتبّع الطلب '+icon('truck'),'tracking/'+o.id):''}${['placed','preparing'].includes(o.status)?btn('إلغاء الطلب','cancel-order','secondary',`data-id="${o.id}"`):''}${o.status==='delivered'&&availableReturns(o).length?goto('طلب إرجاع','return/'+o.id,'secondary'):''}${o.status==='returned'?`<div class="info-box">${icon('return')}تم استلام طلب الإرجاع التجريبي.<br>السبب: ${esc(o.returnReason)}<br>الكمية: ${ar(o.returnQty||1)} · ${esc(o.returnItem?product(o.returnItem).name:'')}<br>لا يتم تنفيذ استرداد مالي حقيقي.</div>`:''}${returnRequests(o)}${btn('إعادة شراء القطع','reorder','secondary',`data-id="${o.id}"`)}${goto('تواصل مع الدعم','support','text-btn')}</div></div>`;}
function tracking(id){const o=orderBy(id);if(!o)return orders();const levels=['placed','preparing','shipped','delivered'];const current=levels.indexOf(o.status);return `${top('تتبّع الطلب')}<div class="page-content"><p class="overline">YOUR ORDER, EVERY STEP</p><h2 class="page-subtitle">${statusText[o.status]}</h2><p class="page-intro"><span class="ltr">${o.id}</span><br>إلى ${esc(addressPlace(o.address))} · ${esc(o.address.area)}</p>${current>=0?`<div class="info-box">${icon('truck')}${o.status==='delivered'?'تم تسليم هذا الطلب التوضيحي':'التوصيل حسب مصدر القطع: العراق نحو يومين، الصين ١٥–٢٠ يوماً (تقديري)'}</div><div class="timeline">${[['placed','تم تأكيد الطلب','تم استلام طلبك بنجاح.'],['preparing','تجهيز القطع','نراجع القطع ونجهزها بعناية.'],['shipped','في الطريق إليك','تم تسليم الشحنة لشركة التوصيل.'],['delivered','تم التسليم','اكتملت رحلة طلبك.']].map(([v,t,s],i)=>`<div class="timeline-step ${i<current?'done':i===current?'current':''}"><i class="timeline-dot"></i><h3>${t}</h3><p>${i<=current?s:'بانتظار المرحلة السابقة'}</p></div>`).join('')}</div>`:`<div class="info-box">${icon('info')}${statusText[o.status]} · لن تستمر مراحل الشحن لهذا الطلب.</div>`}<div class="button-stack">${goto('تواصل مع الدعم','support','secondary')}${goto('تفاصيل الطلب','order/'+o.id,'text-btn')}</div>${current>=0&&o.status!=='delivered'?`<div class="divider"></div><p class="field-note">أداة العرض: انتقلي إلى المرحلة التالية لاختبار تتبّع الطلب.</p>${btn('تغيير الحالة للتجربة','advance-order','secondary',`data-id="${o.id}"`)}`:''}</div>`;}
function returnView(id){const o=orderBy(id);if(!o||o.status!=='delivered'||!availableReturns(o).length)return orderDetail(id);return `${top('طلب إرجاع')}<div class="page-content"><p class="page-intro">اختاري القطعة والسبب. هذا الطلب يحاكي خدمة ما بعد البيع ولا ينفّذ إرجاعاً أو استرداداً حقيقياً.</p><form id="return-form" data-id="${o.id}"><label class="field"><span>القطعة</span><select name="item" id="return-item">${availableReturns(o).map(({line:l,index:i})=>`<option value="${i}">${product(l.id).name} · ${l.size}</option>`).join('')}</select></label><label class="field"><span>الكمية</span><select name="qty" id="return-qty">${Array.from({length:availableReturns(o)[0].remaining},(_,i)=>`<option value="${i+1}">${ar(i+1)}</option>`).join('')}</select></label><label class="field"><span>سبب الإرجاع *</span><select name="reason" required><option value="">اختاري السبب</option><option>المقاس غير مناسب</option><option>القطعة مختلفة عن المتوقع</option><option>يوجد عيب في القطعة</option><option>سبب آخر</option></select></label><label class="field"><span>تفاصيل إضافية (اختياري)</span><textarea name="note" placeholder="أخبرينا بالمزيد"></textarea></label><button class="primary" type="submit">إرسال طلب الإرجاع</button></form></div>`;}
function account(){const u=state.user;return `${top('حسابي')}<div class="account-hero"><div class="avatar">${u?'M':icon('user')}</div><div><h2>${u?'أهلاً، '+esc(u.name):'أهلاً بكِ في M'}</h2><p>${u?`<span class="ltr">${esc(u.phone)}</span>`:'اختياراتك، طلباتك، وكل ما تحبين'}</p></div>${!u?goto('دخول','login','text-btn'):''}</div><div class="page-content account-page-content" style="padding-top:6px"><div class="account-menu-grid">${[['box','طلباتي','orders'],['pin','عناويني','addresses'],['heart','المفضلة','wishlist'],['tag','قسائم الخصم','coupons'],['bell','الإشعارات','notifications'],['chat','خدمة العملاء','support'],['settings','الإعدادات','settings'],['shield','الشروط وسياسة المتجر','policy']].map(([i,n,r])=>`<button class="menu-item" data-go="${r}">${icon(i)}${n}${icon('arrow')}</button>`).join('')}</div><div class="app-footer">MONARCA · IRAQ</div><div class="info-box">${icon('info')}نسخة تفاعلية تجريبية. بياناتك محفوظة في متصفحك فقط.</div></div>`;}
function login(){return `${top('أهلاً بكِ')}<div class="page-content"><p class="overline">YOUR WORLD OF M</p><h2 class="page-subtitle">تفاصيل تخصّك وحدك.</h2><p class="page-intro">دخول تجريبي برقم هاتف عراقي. يمكنك إتمام الشراء كضيفة أيضاً.</p><form id="login-form" novalidate><div class="form-error" id="login-error" role="alert"></div>${!ui.loginStep?`<label class="field"><span>رقم الهاتف</span><input type="tel" dir="ltr" name="phone" autocomplete="tel" placeholder="+964 7XX XXX XXXX" value="${esc(ui.loginPhone)}"></label><button class="primary" type="submit">إرسال رمز تجريبي ${icon('arrow')}</button>`:`<p class="field-note" style="margin-bottom:18px">رمز التحقق التجريبي هو <b class="ltr">1234</b>. لم يتم إرسال رسالة SMS.</p><label class="field"><span>رمز التحقق</span><input name="otp" inputmode="numeric" dir="ltr" placeholder="1234" maxlength="4" autocomplete="one-time-code"></label><button class="primary" type="submit">تسجيل الدخول</button>${btn('تعديل رقم الهاتف','login-back','text-btn')}`}</form><div class="divider"></div>${goto('متابعة التسوق كضيفة','home','secondary')}</div>`;}
function coupons(){return `${top('قسائم الخصم')}<div class="page-content"><p class="overline">A LITTLE SOMETHING FOR YOU</p><h2 class="page-subtitle">لمسة إضافية لاختيارك.</h2><p class="page-intro">قسائم توضيحية قابلة للتجربة في سلة التسوق.</p>${[['M10','10%','ترحيب بأول اختياراتك','خصم ١٠٪ على المنتجات عند شراء ٤٠ USD أو أكثر.'],['FREE100','FREE','التوصيل علينا','توصيل مجاني للطلبات من ٧٥ USD.']].map(([c,v,t,d])=>`<article class="coupon-card"><div class="coupon-value ltr">${v}</div><div class="coupon-body"><b>${t}</b><p>${d}</p><button data-action="use-coupon" data-value="${c}">استخدام <span class="ltr">${c}</span></button></div></article>`).join('')}<div class="info-box">${icon('info')}تطبّق قسيمة واحدة على الطلب. القواعد والأسعار أمثلة لعرض التصميم.</div></div>`;}
function notifications(){return `${top('الإشعارات')}<div class="page-content">${[['box','كل تفاصيل طلبك هنا','تابعي حالة الطلب من التأكيد حتى التسليم.','orders'],['tag','هدية صغيرة لاختيارك','جرّبي الرمز M10 واكتشفي تفاصيل الخصم.','coupons'],['image','صورة واحدة، إلهام جديد','جرّبي البحث بالصورة لاكتشاف قطع مشابهة.','camera']].map(([i,t,d,r])=>`<button class="notification" data-go="${r}" style="width:100%;text-align:right"><span class="empty-icon">${icon(i)}</span><span><h3>${t}</h3><p>${d}</p><small>إشعار توضيحي · اليوم</small></span></button>`).join('')}</div>`;}
function support(){return `${top('خدمة العملاء')}<div class="demo-strip">محادثة تجريبية · الردود آلية لتوضيح التصميم</div><div class="chat-thread"><div class="chat-bubble">أهلاً بكِ في Monarca.<br>كيف يمكننا مساعدتك اليوم؟</div>${ui.chat.map(m=>`<div class="chat-bubble ${m.mine?'mine':''}">${esc(m.text)}</div>`).join('')}<div class="pill-row">${['أين طلبي؟','تفاصيل التوصيل','الاستبدال والإرجاع'].map(t=>btn(t,'chat-quick','pill',`data-value="${t}"`)).join('')}</div></div><form id="chat-form" class="chat-compose"><input name="message" aria-label="رسالتك" placeholder="اكتبي رسالتك..." maxlength="500" autocomplete="off"><button type="submit" aria-label="إرسال">${icon('send')}</button></form><div class="page-content"><p class="field-note">هذه المحادثة الداخلية محاكاة محلية ولا تتصل بموظف. التواصل مع المتجر عبر واتساب متاح من مركز العناية بعد اعتماد رقم المتجر.</p></div>`;}
function settings(){return `${top('الإعدادات')}<div class="page-content"><button class="menu-item" data-action="language">${icon('globe')}اللغة والمنطقة<small>العربية · العراق</small>${icon('arrow')}</button><button class="menu-item" data-action="toggle-notify" aria-pressed="${state.notify}">${icon('bell')}إشعارات التجربة<span class="toggle ${state.notify?'on':''}" style="margin-right:auto"></span></button><button class="menu-item" data-go="policy">${icon('shield')}الخصوصية وشروط التجربة${icon('arrow')}</button>${state.user?`<button class="menu-item" data-action="logout">${icon('logout')}تسجيل الخروج${icon('arrow')}</button>`:goto('تسجيل الدخول','login','menu-item')}<div class="divider"></div><p class="field-note">Monarca · نسخة 1.0<br>عملة العرض: الدولار الأمريكي (USD)<br>Monarca · تصميم حسب مرجع العميل.</p><div class="button-stack">${btn('إعادة ضبط بيانات التجربة','reset','secondary')}</div></div>`;}
function policy(){return `${top('الشروط وسياسة المتجر')}<div class="page-content policy-section"><p class="overline">THE PROTOTYPE, EXPLAINED</p><h2>حول هذه النسخة</h2><p>هذا نموذج تفاعلي لعرض التصميم وتجربة المستخدم، وليس متجراً فعلياً. المنتجات والأسعار والتقييمات والعروض بيانات عرض، وتحتاج اعتماد المتجر قبل الإطلاق.</p><h2>الدفع والطلبات</h2><p>الدفع عبر Visa و Mastercard محاكاة. لا يتم خصم أموال أو إرسال طلبات إلى بائع. لا تدخلي بيانات بطاقة مصرفية حقيقية.</p><h2>التوصيل</h2><p>المتوفر في العراق يصل خلال نحو يومين، والطلب من الصين خلال ١٥–٢٠ يوماً. رسوم التوصيل التجريبية ٤ USD للطلب، والتوصيل مجاني من ٧٥ USD قبل الخصم.</p><h2>الإرجاع والإلغاء</h2><p>يمكن اختبار الإلغاء قبل الشحن، وطلب الإرجاع بعد التسليم. هذه حالات تصميم ولا تمثل سياسة تجارية أو وعداً باسترداد مالي. ستُستبدل بالشروط المعتمدة للعميل.</p><h2>الصور والبيانات</h2><p>الصور المختارة تبقى في جلسة متصفحك ولا ترفع لخادم. سلة التسوق والعنوان والطلبات محفوظة محلياً للتجربة. يمكن مسحها من الإعدادات. تستخدم النسخة صور العرض المقدمة من العميل وصوراً توضيحية مولدة بالذكاء الاصطناعي.</p><div class="button-stack">${goto('تواصل مع الدعم','support','secondary')}</div></div>`;}
const views={home,search,results,categories:categoriesView,camera,'photo-results':photoResults,wishlist:wish,cart:cartView,address:addressForm,addresses,checkout,payment,success,orders,account,login,coupons,notifications,support,settings,policy};
function render(keep=false){const resetBtn=$('#reset-demo');if(resetBtn)resetBtn.disabled=ui.placing;const scroll=app.scrollTop;const [name,id]=ui.route.split('/');let content=plugins.routes[name]?plugins.routes[name](id):name==='product'?productView(id):name==='order'?orderDetail(id):name==='tracking'?tracking(id):name==='return'?returnView(id):(views[name]||home)();app.innerHTML=localizeMarkup(`<main class="route-fade">${content}</main>`);const nav=[['home','home','الرئيسية'],['categories','grid','الأقسام'],['wishlist','heart','المفضلة'],['cart','bag','السلة'],['account','user','حسابي']];const count=state.cart.reduce((s,l)=>s+l.qty,0);const bottomNavEl=$('#bottom-nav');if(bottomNavEl){if(name==='product'){const isAr=(window.MonarcaI18n?.language()||'ar')==='ar';bottomNavEl.classList.add('is-product-bar');bottomNavEl.setAttribute('aria-label',isAr?'شراء المنتج':'Product actions');bottomNavEl.innerHTML=localizeMarkup(`<div class="product-fixed-bar">${btn(icon('bag')+' '+(isAr?'أضف إلى السلة':'Add to bag'),'add-cart','primary')}${btn(isAr?'اشترِ الآن':'Buy now','buy-now','secondary')}</div>`);document.body.classList.add('route-product');}else{bottomNavEl.classList.remove('is-product-bar');document.body.classList.remove('route-product');bottomNavEl.setAttribute('aria-label',localizeText('التنقل الرئيسي'));bottomNavEl.innerHTML=localizeMarkup(nav.map(([r,i,t])=>`<button data-go="${r}" class="${name===r?'active':''}" ${name===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${r==='cart'&&count?`<i class="nav-badge">${ar(count)}</i>`:''}</button>`).join(''));}}renderStudio();app.scrollTop=keep?scroll:ui.scrolls[ui.route]||0;if(!keep){try{window.scrollTo({top:0,left:0,behavior:'instant'});}catch{window.scrollTo(0,0);}if(document.documentElement)document.documentElement.scrollTop=0;if(document.body)document.body.scrollTop=0;}}
function renderStudio(){const nav=$('#page-nav');if(nav)nav.innerHTML='';}
function changeRoute(){closeSheet();let next=decodeURIComponent(location.hash.slice(1)||'home');if(['home','cart','categories','search','account','orders','wishlist'].includes(next))ui.buyNow=null;ui.previous=ui.route;ui.route=next;if(!next.startsWith('product/'))ui.productId=null;for(const hook of plugins.onRoute)hook(next.split('/')[0],next.split('/')[1]);render();}
function filterSheet(){sheet('تصفية وترتيب',`<form id="filter-form"><p class="sheet-label">القسم</p><div class="pill-row">${categories.map(([v,n])=>`<label class="pill" style="display:flex;gap:7px;align-items:center"><input type="radio" name="category" value="${v}" ${ui.category===v?'checked':''}>${n}</label>`).join('')}</div><label class="field" style="margin-top:23px"><span>الترتيب</span><select name="sort">${[['recommended','مختارة لك'],['low','السعر: من الأقل للأعلى'],['high','السعر: من الأعلى للأقل'],['new','الأحدث أولاً']].map(([v,n])=>`<option value="${v}" ${ui.sort===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>الحد الأعلى للسعر</span><select name="max">${[100,200,350,commerce.priceCeiling].map(n=>`<option value="${n}" ${ui.max===n?'selected':''}>${moneyText(n)}</option>`).join('')}</select></label><div class="button-stack"><button type="submit" class="primary">عرض النتائج</button>${btn('إعادة ضبط','reset-filter','secondary')}</div></form>`);}
function addCart(buy){
 const p=product(ui.productId||ui.route.split('/')[1]);const qty=Math.max(1,Math.floor(Number(ui.productQty)||1));
 if(!ui.selectedSize||!p.sizes.includes(ui.selectedSize)||ui.selectedSize===p.unavailable){toast('يرجى اختيار مقاس متوفر أولاً.');return;}
 if(!p.colors.includes(ui.selectedColor)){toast('يرجى اختيار اللون.');return;}
 if(p.stock<1||qty>p.stock){toast('الكمية المطلوبة تتجاوز المخزون المتاح.');return;}
 if(buy){ui.requoteSource=null;const defaultAddress=state.addresses?.find(a=>a.id===state.defaultAddressId);if(defaultAddress){state.address=JSON.parse(JSON.stringify(defaultAddress));state.selectedAddressId=defaultAddress.id;ui.deliveryCity=defaultAddress.city;}ui.buyNowCoupon='';ui.paymentUserSelected=false;ui.buyNow=[{id:p.id,color:ui.selectedColor,size:ui.selectedSize,qty,selected:true}];ui.addressReturn='checkout';ui.pendingOrderId=null;ui.termsAccepted=false;ui.editAddressId=null;ui.addressDraft={city:ui.deliveryCity||''};go('checkout');return;}
 ui.buyNow=null;const line=state.cart.find(l=>l.id===p.id&&l.color===ui.selectedColor&&l.size===ui.selectedSize);
 if(line&&line.qty+qty>p.stock){toast('لديك كمية من هذه القطعة في السلة. تجاوزت الحد المتاح.');return;}
 if(line){line.qty+=qty;line.selected=true;}else state.cart.push({id:p.id,color:ui.selectedColor,size:ui.selectedSize,qty,selected:true});
 save();render(true);sheet('أضيفت إلى حقيبتك',`<div class="mini-product">${photo(p)}<div>${p.name}<small>${colors[ui.selectedColor][0]} · ${ui.selectedSize} · الكمية ${ar(qty)}</small>${money(p.price*qty)}</div></div><div class="button-stack">${goto('عرض الحقيبة '+icon('bag'),'cart')}${btn('متابعة التسوق','close-sheet','secondary')}</div>`);
}
function normalizePhone(v){let s=String(v).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[^0-9]/g,'');if(s.startsWith('00964'))s=s.slice(5);else if(s.startsWith('964'))s=s.slice(3);if(s.startsWith('0'))s=s.slice(1);return /^7\d{9}$/.test(s)?'+964 '+s:null;}
function applyCoupon(code){if(plugins.couponApply)return plugins.couponApply(code);code=code.trim().toUpperCase();const sub=total().subtotal;if(!['M10','FREE100'].includes(code)){toast('رمز الخصم غير صالح. جرّبي M10.');return;}const min=code==='M10'?commerce.couponMin:commerce.shipping.freeFrom;if(sub<min){toast(`هذه القسيمة تحتاج طلباً من ${moneyText(min)}.`);return;}state.coupon=code;save();toast('تم تطبيق القسيمة على طلبك.');render(true);}
function placeOrder(){if(ui.placing)return;if(!shoppingLines().length){go('cart');return;}if(!state.address){ui.addressReturn='checkout';go('address');return;}ui.placing=true;render(true);const snapshot=JSON.parse(JSON.stringify({items:shoppingLines().map(l=>({...l,price:product(l.id).price})),address:state.address,...total(),currency:'USD',payment:ui.payment}));setTimeout(()=>{const order={...snapshot,id:'M-DEMO-'+Date.now().toString().slice(-7),date:new Intl.DateTimeFormat('ar-IQ',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Baghdad'}).format(new Date()),status:'placed'};state.orders.unshift(order);if(!ui.buyNow){for(const bought of snapshot.items){const l=state.cart.find(x=>x.id===bought.id&&x.color===bought.color&&x.size===bought.size);if(l)l.qty-=bought.qty;}state.cart=state.cart.filter(l=>l.qty>0);state.coupon='';}ui.buyNow=null;ui.lastOrder=order.id;state.lastOrder=order.id;ui.navStack=['home','orders'];ui.placing=false;save();go('success');},650);}
function scan(result='match'){if(ui.photoScanning)return;ui.photoResult=result;ui.photoError='';ui.photoScanning=true;render(true);setTimeout(()=>{if(!ui.photoScanning||ui.route!=='camera')return;ui.photoScanning=false;if(result==='error'){ui.photoError='تعذّر تحليل الصورة. حاول مرة أخرى أو اختر صورة أوضح.';render(true);}else go('photo-results');},1400);}
function chatReply(text){if(!text.trim())return;ui.chat.push({mine:true,text:text.trim()});render(true);setTimeout(()=>{ui.chat.push({mine:false,text:text.includes('طلب')?'يمكنك متابعة حالة الطلب من «حسابي ← طلباتي ← تتبّع الطلب». هذه إجابة آلية لتوضيح التجربة.':text.includes('رجاع')||text.includes('استبدال')?'من الطلب المكتمل اختاري «طلب إرجاع» وأضيفي السبب. الشروط النهائية بانتظار اعتماد المتجر.':'يسعدنا مساعدتك. المتوفر في العراق يصل خلال نحو يومين، والطلب من الصين خلال ١٥–٢٠ يوماً. رسوم التوصيل التجريبية ٤ USD، والتوصيل المجاني من ٧٥ USD.'});if(ui.route==='support'){render(true);app.scrollTop=app.scrollHeight;}},650);}
document.addEventListener('click',e=>{if(ui.placing){e.preventDefault();return;}const g=e.target.closest('[data-go]');if(g){e.preventDefault();const route=g.dataset.go;if(route==='address'){ui.addressReturn=ui.route==='checkout'?'checkout':'addresses';ui.addressDraft={};}go(route);return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,v=el.dataset.value,id=el.dataset.id,idx=Number(el.dataset.index);if(plugins.actions[a]){e.preventDefault();plugins.actions[a](el,e);return;}switch(a){
case 'back':back();break;case 'close-sheet':closeSheet();break;
case 'store-contact':openContact(el.dataset.context,el.dataset.order);break;
case 'store-contact-help':closeSheet();go('support');break;
case 'home-category':ui.catalogFilter={};ui.category=v;ui.query='';ui.max=commerce.priceCeiling;ui.sort='recommended';go('results');break;
case 'search-term':ui.query=v;ui.category='all';go('results');break;
case 'filter':filterSheet();break;
case 'reset-filter':ui.category='all';ui.sort='recommended';ui.max=commerce.priceCeiling;filterSheet();break;
case 'clear-filter':ui.category='all';ui.sort='recommended';ui.max=commerce.priceCeiling;render(true);break;
case 'clear-all':ui.category='all';ui.sort='recommended';ui.max=commerce.priceCeiling;ui.query='';render(true);break;
case 'wish':{const n=Number(id),on=state.wish.includes(n);state.wish=on?state.wish.filter(x=>x!==n):[...state.wish,n];save();render(true);toast(on?'تمت الإزالة من المفضلة':'تمت الإضافة إلى المفضلة');break;}
case 'color':ui.selectedColor=v;render(true);break;case 'size':ui.selectedSize=v;render(true);break;
case 'size-guide':{const p=product(ui.productId);sheet('دليل المقاسات',p.cat==='bags'?'<p>مقاس موحّد للعرض. أبعاد الحقيبة والمواد بانتظار اعتماد المنتج من العميل.</p>':`<p>مقاسات توضيحية؛ تُستبدل بجدول المورّد قبل الإطلاق.</p><table class="mini-table"><tr><th>المقاس</th><th>${p.cat==='shoes'?'طول القدم / سم':'محيط الصدر / سم'}</th></tr>${(p.cat==='shoes'?[['37','23.5'],['38','24'],['39','24.5'],['40','25'],['41','25.5']]:[['S','88–92'],['M','92–96'],['L','96–102'],['XL','102–108']]).map(r=>`<tr><td>${r[0]}</td><td class="ltr">${r[1]}</td></tr>`).join('')}</table>`);break;}
case 'accordion':ui.accordion[v]=!ui.accordion[v];render(true);break;
case 'add-cart':addCart(false);break;case 'buy-now':addCart(true);break;
case 'qty-plus':{const l=state.cart[idx];if(l&&l.qty<product(l.id).stock)l.qty++;total();save();render(true);break;}
case 'qty-minus':if(state.cart[idx]?.qty>1){state.cart[idx].qty--;total();save();render(true);}break;
case 'remove-cart':sheet('إزالة القطعة',`<p>هل تريدين إزالة هذه القطعة من السلة؟</p><div class="button-stack">${btn('نعم، إزالة','confirm-remove','primary',`data-index="${idx}"`)}${btn('الاحتفاظ بالقطعة','close-sheet','secondary')}</div>`);break;
case 'confirm-remove':state.cart.splice(idx,1);total();save();closeSheet();render(true);toast('تمت إزالة القطعة');break;
case 'remove-coupon':state.coupon='';save();render(true);toast('تمت إزالة القسيمة');break;
case 'checkout':ui.addressReturn='checkout';go('checkout');break;
case 'edit-address':ui.addressReturn=ui.route==='checkout'?'checkout':'addresses';ui.addressDraft={};go('address');break;
case 'fill-address':{const data={name:'سارة أحمد',phone:'07700000000',city:'بغداد',area:'المنصور',street:'شارع الروّاد',landmark:'قرب مول المنصور',building:'١٢',apartment:'الطابق الأول',note:'بيانات تجريبية'};ui.addressDraft=data;render(true);break;}
case 'delivery':sheet('إلى أين نوصّل اختياراتك؟',`<p>اختاري مدينة لعرض تقدير التوصيل. التفاصيل الكاملة تُضاف عند الطلب.</p><form id="delivery-form" style="margin-top:20px"><label class="field"><span>المدينة</span><select name="city">${cities.map(c=>`<option ${(ui.deliveryCity||state.address?.city||'بغداد')===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="primary" type="submit">حفظ المدينة</button></form>`);break;
case 'payment-method':ui.payment=v;render(true);break;
case 'confirm-order':if(!state.address){ui.addressReturn='checkout';go('address');break;}if(!$('#terms')?.checked){toast('يرجى الموافقة على شروط التجربة.');break;}go('payment');break;
case 'pay-success':go('checkout');break;case 'pay-fail':sheet('لم ينجح الدفع التجريبي',`<p>لم يُخصم أي مبلغ ولم يتم إنشاء طلب. سلتك وعنوانك محفوظان.</p><div class="button-stack">${btn('إعادة المحاولة','close-sheet')}${btn('اختيار بطاقة أخرى','change-card','secondary')}</div>`);break;
case 'change-card':ui.payment=ui.payment==='visa'?'mastercard':'visa';closeSheet();go('checkout');break;
case 'photo-sample':if(ui.photo)URL.revokeObjectURL(ui.photo);ui.photo=null;ui.photoSample=Number(v);ui.photoError='';render(true);break;
case 'scan':scan();break;case 'photo-none':scan('none');break;case 'photo-fail':scan('error');break;
case 'camera-help':sheet('مساعدة الكاميرا',`<p>عند طلب إذن الكاميرا اختاري السماح. إذا لم يتم السماح، يمكنك استخدام «اختر من الصور» لرفع صورة من جهازك.</p><p style="margin-top:12px">بعض أجهزة الكمبيوتر تفتح اختيار الملفات بدلاً من الكاميرا. ارفعي صورة واضحة لقطعة واحدة بصيغة JPG أو PNG أو WebP. الحد الأعلى ١٠ ميغابايت.</p><div class="button-stack">${btn('فهمت','close-sheet')}</div>`);break;
case 'order-filter':ui.orderFilter=v;render(true);break;
case 'advance-order':{const o=orderBy(id),levels=['placed','preparing','shipped','delivered'];if(o&&levels.indexOf(o.status)<3)o.status=levels[levels.indexOf(o.status)+1];save();render(true);toast('تم تحديث الحالة للتجربة');break;}
case 'cancel-order':sheet('إلغاء الطلب',`<p>هل تريدين إلغاء الطلب التجريبي؟</p><form id="cancel-form" data-id="${id}" style="margin-top:18px"><label class="field"><span>سبب الإلغاء</span><select name="reason"><option>تغيير رأيي</option><option>أريد تعديل القطع</option><option>تغيير عنوان التوصيل</option></select></label><div class="button-stack"><button type="submit" class="primary">تأكيد الإلغاء</button>${btn('الاحتفاظ بالطلب','close-sheet','secondary')}</div></form>`);break;
case 'reorder':{const o=orderBy(id);let added=0;o?.items.forEach(l=>{const p=product(l.id);if(l.size===p.unavailable)return;const found=state.cart.find(x=>x.id===l.id&&x.color===l.color&&x.size===l.size);if(found){const q=Math.min(p.stock-found.qty,l.qty);found.qty+=q;added+=q;}else{state.cart.push({id:l.id,color:l.color,size:l.size,qty:Math.min(l.qty,p.stock)});added+=Math.min(l.qty,p.stock);}});save();toast(added?'أضيفت القطع المتوفرة إلى السلة':'لا تتوفر كمية إضافية من هذه القطع');go('cart');break;}
case 'use-coupon':if(!state.cart.length){toast('أضيفي قطعاً للسلة ثم استخدمي الرمز '+v);go('home');}else{applyCoupon(v);go('cart');}break;
case 'login-back':ui.loginStep=false;render(true);break;
case 'chat-quick':chatReply(v);break;
case 'toggle-notify':state.notify=!state.notify;save();render(true);toast(state.notify?'تم تفعيل إعداد الإشعارات التجريبي':'تم إيقاف إعداد الإشعارات التجريبي');break;
case 'language':languageSheet();break;
case 'logout':state.user=null;save();render(true);toast('تم تسجيل الخروج');break;
case 'reset':resetPrompt();break;
}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.id)return;e.preventDefault();const d=Object.fromEntries(new FormData(form));if(plugins.forms[form.id]){plugins.forms[form.id](form,d,e);return;}switch(form.id){
case 'search-form':ui.query=d.query.trim();ui.category='all';ui.max=commerce.priceCeiling;go('results');break;
case 'filter-form':ui.category=d.category||'all';ui.sort=d.sort;ui.max=Number(d.max);closeSheet();render();break;
case 'coupon-form':applyCoupon(d.code);break;
case 'address-form':{ui.addressDraft=d;const phone=normalizePhone(d.phone);let msg='';if(d.name.trim().length<3)msg='يرجى إدخال الاسم الكامل.';else if(!phone)msg='أدخل رقم هاتف عراقي صحيحاً: 07 متبوعاً بـ 9 أرقام، أو +964 ثم 7 و9 أرقام.';else if(!cities.includes(d.city))msg='يرجى اختيار المدينة.';else if(!d.area.trim()||!d.street.trim())msg='يرجى إدخال الحي والشارع لإكمال عنوان التوصيل.';else if(!d.landmark.trim())msg='يرجى إضافة أقرب نقطة دالة لتسهيل التوصيل.';if(msg){$('#address-error').textContent=msg;$('#address-error').classList.add('visible');$('#address-error').scrollIntoView({block:'center',behavior:'smooth'});return;}state.address={...d,phone};ui.deliveryCity=d.city;state.deliveryCity=d.city;ui.addressDraft={};save();toast('تم حفظ عنوان التوصيل');go(ui.addressReturn==='checkout'&&(ui.buyNow||state.cart).length?'checkout':'addresses');break;}
case 'delivery-form':ui.deliveryCity=d.city;state.deliveryCity=d.city;save();closeSheet();if(state.address&&state.address.city!==d.city){ui.addressReturn='addresses';ui.addressDraft={city:d.city,name:state.address.name,phone:state.address.phone,area:'',street:'',landmark:'',building:'',apartment:''};go('address');toast('أكملي عنوان المدينة الجديدة. عنوانك السابق محفوظ حتى التأكيد.');}else{ui.addressDraft.city=d.city;render(true);toast('المدينة المختارة: '+d.city);}break;
case 'login-form':{const err=$('#login-error');if(!ui.loginStep){const p=normalizePhone(d.phone);if(!p){err.textContent='يرجى إدخال رقم هاتف عراقي صحيح.';err.classList.add('visible');return;}ui.loginPhone=p;ui.loginStep=true;render();}else if(d.otp.replace(/[٠-٩]/g,n=>'٠١٢٣٤٥٦٧٨٩'.indexOf(n))!=='1234'){err.textContent='الرمز غير صحيح. رمز التجربة هو 1234.';err.classList.add('visible');}else{state.user={name:'ضيفة M',phone:ui.loginPhone};save();ui.loginStep=false;toast('تم تسجيل الدخول التجريبي');go('account');}break;}
case 'chat-form':chatReply(d.message);break;
case 'cancel-form':{const o=orderBy(form.dataset.id);if(o&&['placed','preparing'].includes(o.status)){o.status='cancelled';o.cancelReason=d.reason;save();}closeSheet();render(true);toast('تم إلغاء الطلب التجريبي');break;}
case 'return-form':{const o=orderBy(form.dataset.id);if(o&&o.status==='delivered'){const itemIndex=Number(d.item),available=availableReturns(o).find(r=>r.index===itemIndex);if(!available||!d.reason)return;o.returnRequests=o.returnRequests||[];o.returnRequests.push({itemIndex,reason:d.reason,qty:Math.min(Number(d.qty)||1,available.remaining),note:d.note,status:'requested'});save();try{window.MonarcaAPI?.submitReturn?.(o.id,itemIndex,d.reason,d.qty,d.note);}catch(_){}toast('تم استلام طلب الإرجاع التجريبي');go('order/'+o.id);}break;}
}});
document.addEventListener('input',e=>{if(e.target.closest('#address-form'))ui.addressDraft=Object.fromEntries(new FormData($('#address-form')));});
document.addEventListener('change',e=>{for(const hook of plugins.change){if(hook(e))return;}if(['photo-file','camera-file'].includes(e.target.id)){const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){ui.photoError='يرجى اختيار ملف صورة صالح.';render(true);return;}if(file.size>10*1024*1024){ui.photoError='الصورة أكبر من ١٠ ميغابايت. اختاري صورة أصغر.';render(true);return;}if(ui.photo)URL.revokeObjectURL(ui.photo);ui.photo=URL.createObjectURL(file);ui.photoSample=null;ui.photoError='';render(true);}if(e.target.id==='return-item'){const o=orderBy(ui.route.split('/')[1]),l=availableReturns(o).find(r=>r.index===Number(e.target.value));$('#return-qty').innerHTML=Array.from({length:l.remaining},(_,i)=>`<option value="${i+1}">${ar(i+1)}</option>`).join('');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlays.innerHTML)closeSheet();if(e.key==='Tab'&&overlays.innerHTML){const els=[...overlays.querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled),first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.file-label')){e.preventDefault();e.target.querySelector('input').click();}});
overlays.addEventListener('click',e=>{if(e.target.classList.contains('overlay'))closeSheet();});
function resetPrompt(){sheet('إعادة ضبط التجربة',`<p>سيتم مسح السلة والعنوان والمفضلة والطلبات المحفوظة على هذا المتصفح، وإعادة الطلبات التوضيحية.</p><div class="button-stack">${btn('نعم، إعادة الضبط','reset-confirm')}${btn('إلغاء','close-sheet','secondary')}</div>`);}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="reset-confirm"]')){if(ui.placing)return;state=initial();const currentRoute=ui.route;clearTimeout(ui.toastTimer);for(const k of Object.keys(ui))delete ui[k];Object.assign(ui,JSON.parse(JSON.stringify(initialUiSeed)),{route:currentRoute,deliveryCity:'',addressReturn:'addresses'});for(const hook of plugins.reset)hook();save();closeSheet();go('home');toast('تمت إعادة ضبط التجربة');}});
$('#reset-demo')?.addEventListener('click',resetPrompt);
window.addEventListener('hashchange',changeRoute);
try{if(window.Capacitor?.Plugins?.App?.addListener){window.Capacitor.Plugins.App.addListener('backButton',()=>{const overlays=document.getElementById('overlay-root');if(overlays&&overlays.children.length>0&&overlays.innerHTML.trim()!==''){closeSheet();return;}if(ui.route!=='home'){back();return;}window.Capacitor?.Plugins?.App?.exitApp?.();});}}catch(_){}

window.Monarca={
 get state(){return state;},ui,products,product,categories,colors,cities,commerce,applyDemoPricing,roundMoney,moneyText,storageKey:key,money,ar,esc,addressPlace,icon,photo,photoArt,card,grid,top,btn,goto,empty,go,back,render,save,toast,sheet,closeSheet,total,summary,normalizePhone,shoppingLines,cardName,cardBrand,isPreview,contactDetails,contactButton,openContact,bestSellerStats,bestSellerGrid,t:localizeText,locale,
 setState(next){state=next;save();render();},
 register(module){
  Object.assign(plugins.routes,module.routes||{});Object.assign(plugins.actions,module.actions||{});Object.assign(plugins.forms,module.forms||{});
  if(module.reset)plugins.reset.push(module.reset);if(module.change)plugins.change.push(module.change);if(module.onRoute)plugins.onRoute.push(module.onRoute);
  if(module.pricing)plugins.pricing=module.pricing;if(module.shoppingLines)plugins.shoppingLines=module.shoppingLines;if(module.couponApply)plugins.couponApply=module.couponApply;
  if(module.onRoute)module.onRoute(ui.route.split('/')[0],ui.route.split('/')[1]);render(true);
 },
 get registeredRoutes(){return Object.keys(plugins.routes);}
};

